{
  "steps": [
    "1) Triage alert context and immediate containment: retrieve alert details, affected account ACC-D0004-RT00, timestamps, related transactions and counterparties to determine urgency and scope.",
    "2) Flow analysis (Breadth-first): trace incoming and outgoing flows from the root account to identify scatter (splits) and gather (consolidations) patterns, build candidate flow graphs for the alert amount INR 1,382,885.67 and nearby amounts/timestamps.",
    "3) Flow validation and hypothesis testing: compute conservation checks on candidate graphs, identify nodes that break conservation or show layering, and compare alternate graph runs to prioritize suspicious paths.",
    "4) Counterparty and provenance checks: pull KYC/business registry info for high-priority counterparties, review their transaction histories and any connections to known high-risk entities or jurisdictions.",
    "5) Temporal and behavior analysis: examine timing, frequency, and amount patterns for scatter/gather behavior (e.g., many small splits followed by consolidation), flag anomalous patterns versus normal commercial flows.",
    "6) Regulatory context: identify relevant AML/CTR thresholds, reporting obligations and specific clauses that apply to INR 1,382,885.67 and scatter/gather typologies for our jurisdiction.",
    "7) Consolidate findings and prepare investigator report: assemble flow graphs, KYC findings, regulatory implications, uncertainty/confidence levels, and recommended next actions (freeze, file STR, escalate).",
    "8) Final quality review: perform conservation recalculation and sanity checks on the assembled evidence, then finalize the report for filing or escalation."
  ],
  "handoffs": [
    {
      "task_id": "HO-FLOW",
      "target_agent": "flow_tracer",
      "objective": "Perform primary flow investigation from root ACC-D0004-RT00: retrieve alert context and all recent transactions for the account; construct candidate fund-flow graphs spanning up to 3 hops (inbound and outbound); run flow conservation checks; compare alternate graph runs to surface top 5 suspicious paths that account for or redistribute the INR 1,382,885.67 amount. Produce graph artifacts, conservation summaries, and recommended top nodes for KYC enrichment.",
      "allowed_tool_budget": 4
    },
    {
      "task_id": "HO-BENIGN",
      "target_agent": "benign_investigator",
      "objective": "For the top 10 counterparties identified by flow_tracer, retrieve KYC profiles, commercial registry records, and counterparty transaction histories to assess legitimacy. Compute risk indicators (ownership anomalies, shell-company signals, prior suspicious activity) and flag any clear benign commercial explanations. Deliver structured KYC dossiers and risk scores for each counterparty.",
      "allowed_tool_budget": 5
    },
    {
      "task_id": "HO-REG",
      "target_agent": "regulatory_analyst",
      "objective": "Identify applicable regulatory requirements and reporting thresholds for INR 1,382,885.67 and for scatter/gather money movement in our jurisdiction. Return the relevant statutes/clauses, short summary of filing obligations (STR/CTR), timelines, and any legal definitions that bear on whether the activity meets the reporting standard.",
      "allowed_tool_budget": 2
    },
    {
      "task_id": "HO-CRITIC",
      "target_agent": "reporter_critic",
      "objective": "Independently recompute flow conservation for the final candidate graphs and critique the evidence package: check for calculation errors, missing links, or alternative benign explanations. Provide a short QC checklist and a go/no-go recommendation for filing/escalation with confidence levels.",
      "allowed_tool_budget": 2
    }
  ]
}

